import marshal
from flask import Flask, request

app = Flask(__name__)

@app.route('/unmarshal')
def unmarshal_data():
    '''
    Ambil data yang dimarshalling dari permintaan menggunakan 'data' sebagai kunci. 
    Unmarshal data tersebut dengan mengonversinya dari hex ke bytes,
    Kembalikan data yang telah dimarshalling.
    '''
    data_hex = request.args.get('data')
    if not data_hex:
        return "Parameter 'data' tidak ditemukan dalam permintaan.", 400

    try:
        data_bytes = bytes.fromhex(data_hex)
        unmarshalled_data = marshal.loads(data_bytes)
        return str(unmarshalled_data)
    except ValueError:
        return "Data hex tidak valid.", 400
    except Exception as e:
        return f"Terjadi kesalahan: {str(e)}", 500
