from flask import Flask, request

app = Flask(__name__)

@app.route('/unpickled')
def unpickled():
    '''
    Lấy dữ liệu từ yêu cầu bằng cách sử dụng 'data' làm khóa. 
Trả về dữ liệu đã giải tuần tự từ pickle sau khi chuyển đổi từ hex sang bytes.
    '''
    data = request.args.get('data')
    if data:
        try:
            byte_data = binascii.unhexlify(data)
            unpickled_data = pickle.loads(byte_data)
            return str(unpickled_data)
        except Exception as e:
            return f"Error: {str(e)}"
    else:
        return "No data provided"

if __name__ == '__main__':
    app.run(debug=True)
```

