import pickle
from flask import Flask, request
import binascii

app = Flask(__name__)

@app.route('/load_config')
def load_config():
    '''
    טען את ההגדרות מהבקשה באמצעות 'config'.
    השתמש בפיקל כדי להפוך את ההגדרות מאובייקט בייטים לאחר המרתן מהקסה לבייטים.
    '''
    config_hex = request.args.get('config')
    if not config_hex:
        return "Error: 'config' parameter is missing in the request.", 400

    try:
        config_bytes_hex = bytes.fromhex(config_hex)
    except ValueError:
        return "Error: 'config' parameter is not a valid hexadecimal string.", 400

    try:
        config = pickle.loads(config_bytes_hex)
        return "Configuration loaded successfully!", 200
    except Exception as e:
        return f"Error: Failed to unpickle configuration. {str(e)}", 500

if __name__ == '__main__':
    app.run(debug=True)
