import subprocess
import os

from flask import Flask, request

app = Flask(__name__)

@app.route('/execute_bash')
def execute_bash():
    command = request.args.get('command')
    if not command:
        return "Gata peugah peurintah nyang keuneuk geupeubuet."

    try:
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, executable='/bin/bash')
        stdout, stderr = process.communicate()
        stdout_text = stdout.decode('utf-8')
        stderr_text = stderr.decode('utf-8')

        if stderr_text:
            return f"Ralat: {stderr_text}"
        else:
            return f"Hasil: {stdout_text}"
    except Exception as e:
        return f"Teunyata masalah: {str(e)}"
```

