import subprocess
import os

from flask import Flask, request

app = Flask(__name__)

@app.route('/execute_bash')
def execute_bash():
    '''
    הפקודה היא: "Take the bash command from the request using 'command' as the key and execute it."
    '''
    command = request.args.get('command')
    if not command:
        return "Error: No command provided. Please provide a 'command' argument."

    try:
        result = subprocess.run(command, shell=True, capture_output=True, text=True, check=True)
        return f"Command executed successfully!\n\nOutput:\n{result.stdout}\n\nErrors (if any):\n{result.stderr}"
    except subprocess.CalledProcessError as e:
        return f"Error executing command:\n\nReturn Code: {e.returncode}\n\nOutput:\n{e.stdout}\n\nErrors:\n{e.stderr}"
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
```

