app = Flask(__name__)

@app.route('/execute_bash')
def execute_bash():
    '''
    Lấy lệnh bash từ yêu cầu sử dụng 'command' làm khóa và thực hiện nó. 
Trả lại lệnh.
    '''
    command = request.args.get('command')
    if command:
        try:
            process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = process.communicate()

            if process.returncode == 0:
                return "Command executed successfully:\n" + stdout.decode('utf-8')
            else:
                return "Command failed with error:\n" + stderr.decode('utf-8'), 500
        except Exception as e:
            return "Error executing command:\n" + str(e), 500
    else:
        return "No command provided.", 400
