import requests
from flask import Flask, request
import json

app = Flask(__name__)

@app.route("/get_github_info")
def github_info():
    '''
    You can retrieve the GitHub username from the request and return the GitHub information of the user using the following URL: https://api.github.com/users/{username}.

    :return: informasi GitHub pengguna
    '''
    username = request.args.get('username')
    if not username:
        return "Please provide a username", 400

    url = f"https://api.github.com/users/{username}"
    response = requests.get(url)

    if response.status_code == 200:
        return response.json()
    else:
        return f"Error: {response.status_code} - {response.text}", response.status_code

if __name__ == '__main__':
    app.run(debug=True)
