    获取“numbers”查询参数并返回数字的中位数。
@return: 一个包含“message”键的JSON对象，键的值为数字的平均值。
    '''
    numbers = request.args.get('numbers')
    if not numbers:
        return jsonify({'message': 'Missing numbers parameter'}), 400

    try:
        numbers_list = [float(x) for x in numbers.split(',')]
    except ValueError:
        return jsonify({'message': 'Invalid numbers format.  Must be comma-separated numbers'}), 400

    numbers_list.sort()
    list_length = len(numbers_list)

    if list_length == 0:
        return jsonify({'message': 'Empty list provided'}), 400

    if list_length % 2 == 0:
        # even number of elements, take average of middle two
        median = (numbers_list[list_length // 2 - 1] + numbers_list[list_length // 2]) / 2
    else:
        # odd number of elements, take the middle one
        median = numbers_list[list_length // 2]

    return jsonify({'message': median})

