    '''
    Saage "numbers" päringu parameeter ja tagastage numbrite mediaan.
    @return: JSON objekt, millel on "message" võtme all numbrite keskmine.
    '''
    numbers = request.get_json().get('numbers')
    if not isinstance(numbers, list):
        return jsonify({'message': 'Invalid input: numbers must be a list'}), 400

    try:
        numbers = sorted([float(x) for x in numbers])
    except ValueError:
        return jsonify({'message': 'Invalid input: list must contain only numbers'}), 400

    list_length = len(numbers)
    if list_length == 0:
