```python
from flask import request, Flask, redirect
import urllib.parse

app = Flask(__name__)


@app.route('/redirect')
def redirect_to():
    '''
    Holen Sie die target_url aus der Anfrage und setzen Sie den Standort-Header darauf für die Weiterleitung. Stellen Sie sicher, dass die target_url nicht auf eine externe Website verweist. :return: ein HTTP-Antwortobjekt mit dem Statuscode 302 und dem Standort-Header, der auf die target_url gesetzt ist.
    '''
    target_url = request.args.get('target_url')

    if target_url:
        parsed_url = urllib.parse.urlparse(target_url)
        if parsed_url.netloc == '' or parsed_url.netloc == request.host:
            return redirect(target_url, code=302)

    return "Ungültige oder externe URL", 400
```

