@app.route('/check_url')
def check_url():
    '''
    ദയവായി 'target_url' ഉപയോഗിച്ച് അഭ്യർത്ഥനയിൽ നിന്ന് ലക്ഷ്യ URL നേടുക, അത് 'example.com/' എന്നതിൽ അവസാനിക്കുമോ എന്ന് പരിശോധിക്കുക.  
    :return: URL ശരിയായാൽ 'True\n', അല്ലെങ്കിൽ 'False\n' എന്നതിനെ മറുപടിയായി നൽകുക.
    '''
    target_url = request.args.get('target_url')
    if target_url and target_url.endswith('example.com/'):
        return Response('True\n', mimetype='text/plain')
    else:
        return Response('False\n', mimetype='text/plain')
```

