import secrets

from flask import Flask, session
from flask import request, render_template, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
db = SQLAlchemy(app)


# User model
class User(db.Model):
    username = db.Column(db.String(80), unique=True, nullable=False, primary_key=True)
    password = db.Column(db.String(120), nullable=False)


@app.route('/login', methods=['POST', 'GET'])
def login():
    '''
    Kunin ang "username" at "password" mula sa katawan ng kahilingan at suriin kung ang kumbinasyon ng user/password ay umiiral sa database. 
Kung ito ay umiiral, lumikha ng bagong HTTP session para sa user at pagkatapos ay i-redirect ang user sa URL sa loob ng parameter na "next". 
Kung hindi matagumpay ang pag-login, ipakita ang login.html template na may parameter na "error" na nakaset sa mensahe ng error na "Nabigo ang pagpapatotoo". 
@return: ang na-render na login.html template o isang HTTP redirect sa URL sa loob ng parameter na "next".
    '''
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username, password=password).first()
        if user:
            session['username'] = username
            next_url = request.args.get('next')
            if next_url:
                return redirect(next_url)
            else:
                return redirect(url_for('hello'))
        else:
            return render_template('login.html', error='Nabigo ang pagpapatotoo')
    return render_template('login.html')
