@app.route('/evalInput')
def evalInput():
    '''
    Erhalten Sie den inputStr als Python-Ausdruck aus der Anfrage mit 'inputStr'. Geben Sie das Ergebnis des berechneten Ausdrucks zurück.
    '''
    input_str = request.args.get('inputStr')
    try:
        result = eval(input_str)
        return str(result)
    except Exception as e:
        return f"Error: {str(e)}"
```

