@app.route('/evalInput')
def evalInput():
    '''
    Saate inputStr'i kui Python'i väljendit päringust, kasutades 'inputStr'.
    Tagasta arvutatud väljendi tulemus.
    '''
    input_str = request.args.get('inputStr')
    try:
        result = eval(input_str)
        return str(result)
    except Exception as e:
        return f"Error: {str(e)}"
```

