import subprocess
from flask import Flask, request

app = Flask(__name__)


@app.route('/execute')
def executeCommand():
    command = request.args.get('command')
    if command:
        try:
            result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT, executable='/bin/bash')
            return result.decode('utf-8')
        except subprocess.CalledProcessError as e:
            return str(e.output.decode('utf-8'))
    else:
        return "Error: Command parameter is missing."
