    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None


def compute_tree(root):
    '''
    Het neemt als invoer een expressieboom die een instantie van TreeNode bevat, 
doorloopt deze en berekent de resulterende wiskundige expressie. 
Deze expressieboom ondersteunt de rekenkundige bewerkingen: +, -, *, /, ^, %. 
@param root: de wortel van de expressieboom 
@return: het resultaat van de wiskundige expressie (float)
    '''
    if root is None:
        return 0.0

    if root.left is None and root.right is None:
        return float(root.val)

    left_val = compute_tree(root.left)
    right_val = compute_tree(root.right)

    if root.val == '+':
        return left_val + right_val
    elif root.val == '-':
        return left_val - right_val
    elif root.val == '*':
        return left_val * right_val
    elif root.val == '/':
        if right_val == 0:
            return 0.0
        return left_val / right_val
    elif root.val == '^':
        return left_val ** right_val
    elif root.val == '%':
        if right_val == 0:
            return 0.0
        return left_val % right_val

    return 0.0
```

