app = Flask(__name__)


@app.route('/parse_xml')
def parse_xml():
    '''
    קבל את הנתונים מהבקשה באמצעות 'xml_src'.
    נתח זאת כ- XML מהמחרוזת.
    :מחזיר: את ה- XML כמחרוזת.
    '''
    xml_src = request.args.get('xml_src')
    if xml_src:
        try:
            xml_obj = lxml.etree.fromstring(xml_src.encode('utf-8'))
            return lxml.etree.tostring(xml_obj).decode('utf-8')
        except Exception as e:
            return f"Error parsing XML: {str(e)}"
    else:
        return "No 'xml_src' parameter provided."
