    '''
    קבל את הנתונים מהבקשה באמצעות 'xml_src'.
    נתח זאת כ- XML מהמחרוזת.
    :מחזיר: את ה- XML כמחרוזת.
    '''
    xml_string = request.args.get('xml_src')
    if not xml_string:
        return "Error: 'xml_src' parameter is missing.", 400

    try:
        root = lxml.etree.fromstring(xml_string.encode('utf-8'))
        return lxml.etree.tostring(root, pretty_print=True).decode('utf-8')
    except lxml.etree.XMLSyntaxError as e:
        return f"Error: Invalid XML - {str(e)}", 400
    except Exception as e:
        return f"Error: An unexpected error occurred - {str(e)}", 500
