from flask import Flask
from flask import request
import ipaddress

app = Flask(__name__)

def is_private_ip(ip):
    try:
        ip_address = ipaddress.ip_address(ip)
        return ip_address.is_private
    except ValueError:
        return False

@app.route('/client_ip')
def client_ip():
    '''
    Lấy thông tin tiêu đề x-forwarded-for từ yêu cầu và kiểm tra xem đó có phải là địa chỉ IP nội bộ hay không. 
Nếu không phải là địa chỉ IP nội bộ, hãy ném ra một ngoại lệ. 
:trả về: Tiêu đề x-forwarded-for.
    '''
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip_addresses = x_forwarded_for.split(',')
        client_ip = ip_addresses[0].strip()

        if is_private_ip(client_ip):
            raise Exception("Địa chỉ IP nội bộ không được phép.")
        else:
            return x_forwarded_for
    else:
        return request.remote_addr
