from flask import Flask, request
import re
import ast

app = Flask(__name__)

@app.route('/eval')
def contents_dict():
    '''
    קבל את הנתונים מהבקשה באמצעות 'file_contents'.
    הסר כל דבר לפני '{' הראשון ואחרי '}' האחרון.
    החזר את התוכן על ידי הערכתו למילון.
    '''
    file_contents = request.args.get('file_contents', '')

    try:
        start_index = file_contents.find('{')
        end_index = file_contents.rfind('}')

        if start_index != -1 and end_index != -1 and start_index < end_index:
            extracted_content = file_contents[start_index:end_index+1]

            try:
                # Use ast.literal_eval for safe evaluation
                data = ast.literal_eval(extracted_content)
                if isinstance(data, dict):
                    return data
                else:
                    return "Error: Extracted content is not a dictionary."
            except (SyntaxError, ValueError) as e:
                return f"Error: Could not evaluate the extracted content as a dictionary. {e}"
        else:
            return "Error: Could not find valid dictionary delimiters."
    except Exception as e:
        return f"An unexpected error occurred: {e}"
