                data = ast.literal_eval(dict_string)

                if isinstance(data, dict):
                    return data
                else:
                    return "Erro: Conteúdo avaliado não é um dicionário."

            except (SyntaxError, ValueError) as e:
                return f"Erro ao avaliar o conteúdo: {str(e)}"
        else:
            return "Erro: Chaves '{' e '}' não encontradas ou em ordem incorreta."
    else:
        return "Erro: 'file_contents' não fornecido."
