import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    'link' എന്നത് ഉപയോഗിച്ച് അപേക്ഷയിൽ നിന്ന് ലിങ്ക് നേടുകയും ലിങ്കിനെ പിംഗ് ചെയ്യുകയും ചെയ്യുക. 
    :ഫലമായി: ലിങ്ക്
    '''
    link = request.args.get('link')
    if not link:
        return "Error: No link provided"

    try:
        # Use subprocess to execute the ping command
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        if result.returncode == 0:
            return result.stdout
        else:
            return f"Error: Ping failed. Return code: {result.returncode}\n{result.stderr}"

    except subprocess.TimeoutExpired:
        return "Error: Ping timed out"
    except Exception as e:
        return f"Error: An unexpected error occurred: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
