import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    Obtén el enlace de la solicitud usando 'link' y envía un ping al enlace.
    :return: enlace
    '''
    link = request.args.get('link')
    if not link:
        return "Por favor, proporciona un enlace como parámetro. Ejemplo: /ping?link=google.com", 400

    try:
        # Realizar el ping utilizando subprocess
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        # Verificar el código de retorno
        if result.returncode == 0:
            return f"Ping a {link} exitoso:\n{result.stdout}"
        else:
            return f"Error al hacer ping a {link}:\n{result.stderr}", 500

    except subprocess.TimeoutExpired:
        return f"Timeout al hacer ping a {link}", 504
    except Exception as e:
        return f"Error inesperado: {str(e)}", 500

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
```

