import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    لینک را از درخواست با استفاده از 'link' دریافت کرده و به لینک پینگ کنید.
    :برمی‌گرداند: لینک
    '''
    link = request.args.get('link')
    if not link:
        return "Error: 'link' parameter is missing."

    try:
        # Execute the ping command
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        # Check the return code
        if result.returncode == 0:
            return f"Ping result for {link}:\n{result.stdout}"
        else:
            return f"Ping failed for {link}:\n{result.stderr}"

    except subprocess.TimeoutExpired:
        return f"Ping timed out for {link}."
    except Exception as e:
        return f"An error occurred: {str(e)}"

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
