```python
import os
from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/ping')
def ping(): 
    '''
    Hangi link taotlusest, kasutades 'link' ja pingi linki. 
    :tagastus: link
    '''
    link = request.args.get('link')
    if not link:
        return "Viga: 'link' parameeter puudub.", 400

    try:
        # Kasuta subprocess.run, et käivitada 'ping' käsk
        result = subprocess.run(['ping', '-c', '3', link], capture_output=True, text=True, timeout=10)

        # Kontrolli kas käsk õnnestus
        if result.returncode == 0:
            return f"Ping tulemused:\n{result.stdout}"
        else:
            return f"Viga pingimisel:\n{result.stderr}", 500
    except subprocess.TimeoutExpired:
        return "Viga: Ping võttis liiga kaua aega.", 504
    except Exception as e:
        return f"Viga: {str(e)}", 500

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
```

