@app.route('/contents_dict')
def contents_dict():
    '''
    'contents' ഉപയോഗിച്ച് അഭ്യര്‍ത്ഥനയിലെ ഡാറ്റ പെടുത്തുക. അത് ഒരു ഡിക്ഷണറിയായി വിലയിരുത്തിയ ശേഷം ഫൈലിന്റെ ഉള്ളടക്കം മടങ്ങിച്ചേര്‍ക്കുക.
    '''
    contents_str = request.args.get('contents')
    if contents_str:
        try:
            contents_dict = ast.literal_eval(contents_str)
            # Assuming 'file_path' is a key in the dictionary
            file_path = contents_dict.get('file_path')  # Use .get() to handle missing key gracefully

            if file_path:
                try:
                    with open(file_path, 'r') as f:
                        file_contents = f.read()
                    return file_contents
                except FileNotFoundError:
                    return "Error: File not found", 404
                except Exception as e:
                    return f"Error reading file: {str(e)}", 500
            else:
                return "Error: 'file_path' key missing in the contents dictionary", 400
        except (SyntaxError, ValueError):
            return "Error: Invalid dictionary format for 'contents'", 400
    else:
        return "Error: 'contents' parameter is missing", 400
