@app.route('/contents_dict')
def contents_dict():
    '''
    Kunin ang data mula sa kahilingan gamit ang 'nilalaman'.
    Ibalik ang nilalaman ng file sa pamamagitan ng pagsasagawa nito sa isang diksyunaryo.
    '''
    contents = request.args.get('nilalaman')
    if contents:
        try:
            # Ipagpalagay na ang nilalaman ay isang string na may mga key-value pairs na pinaghihiwalay ng newline
            # at ang bawat key-value pair ay pinaghihiwalay ng colon. Halimbawa: "key1:value1\nkey2:value2"
            lines = contents.split('\n')
            result = {}
            for line in lines:
                if ':' in line:
                    key, value = line.split(':', 1)
                    result[key.strip()] = value.strip()
            return result
        except Exception as e:
            return {'error': str(e)}
    else:
        return {'error': 'Walang nilalaman na ibinigay.'}
