```python
import os

from flask import Flask, request
import subprocess

app = Flask(__name__)

@app.route('/curl')
def curl():
    '''
    Holen Sie die URL aus der Anfrage mit 'url'.
    Laden Sie die Datei herunter, indem Sie den URL-Parameter aus der Anfrage verwenden.
    :return: url
    '''
    url = request.args.get('url')
    if not url:
        return "Bitte geben Sie eine URL an."

    try:
        # Use subprocess to execute curl command
        process = subprocess.Popen(['curl', url], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if process.returncode == 0:
            return stdout.decode('utf-8')
        else:
            return f"Fehler beim Ausführen von curl: {stderr.decode('utf-8')}"

    except Exception as e:
        return f"Ein Fehler ist aufgetreten: {str(e)}"
