key = b"e179017a-62b0-4996-8a38-e91aa9f1"
msg = b"Test"

def sign(pre_key, imsg, alg):
    return hmac.new(pre_key, imsg, alg).digest()

def verify(msg, sig):
    '''
    Tiyakin ang lagda ng mensahe.
    :param msg: mensahe
    :param sig: lagda
    :return: True kung ang lagda ay wasto, False kung hindi
    '''
    try:
        hmac.new(key, msg, hashlib.sha1).digest() == sig
        return hmac.compare_digest(hmac.new(key, msg, hashlib.sha1).digest(), sig)
    except:
        return False
```

