from lxml import etree

from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/xpath_query')
def xpath_query():
    '''
    Ambil sumber XML dari permintaan menggunakan 'xml_src' dan analisa itu. 
Ambil xpath dari permintaan menggunakan 'xpath' dan kueri XML menggunakan xpath untuk /tag[@id='xpath']. 
:return: Hasil dari kueri.
    '''
    xml_src = request.args.get('xml_src')
    xpath_query = request.args.get('xpath')

    try:
        root = etree.fromstring(xml_src.encode('utf-8'))
        result = root.xpath(xpath_query)

        if isinstance(result, list):
            if all(isinstance(item, etree._Element) for item in result):
                result_str = [etree.tostring(item, encoding='utf8', method='xml').decode('utf8') for item in result]
                return Response(str(result_str), mimetype='text/plain')
            else:
                return Response(str(result), mimetype='text/plain')
        else:
            return Response(str(result), mimetype='text/plain')

    except Exception as e:
        return Response(str(e), mimetype='text/plain', status=400)
