        result = root.xpath(xpath_query)

        if isinstance(result, list):
            if len(result) == 0:
                return "[]"

            stringified_result = []
            for element in result:
                if isinstance(element, etree._Element):
                    stringified_result.append(etree.tostring(element, encoding='utf8', method='xml').decode('utf8'))
                else:
                    stringified_result.append(str(element))  # Convert other types to string

            return "[" + ", ".join(stringified_result) + "]"
        else:
            return str(result)

