app = Flask(__name__)

@app.route('/xpath_query')
def xpath_query():
    '''
    从请求中获取XML源，使用'xml_src'并进行解析。
    从请求中获取xpath，使用'xpath'并根据xpath查询XML，查询路径为/tag[@id='xpath']。
    :返回：查询的结果。
    '''
    xml_src = request.args.get('xml_src')
    xpath_query = request.args.get('xpath')

    if not xml_src or not xpath_query:
        return "请提供xml_src和xpath参数", 400

    try:
        root = etree.fromstring(xml_src.encode('utf-8'))
        result = root.xpath(xpath_query)

        if isinstance(result, list):
            if len(result) == 0:
                return "没有找到匹配的节点", 404

            # Convert to string for simple cases
            string_results = []
            for res in result:
                if isinstance(res, etree._Element):
                    string_results.append(etree.tostring(res, encoding='utf-8').decode('utf-8'))
                else:
                    string_results.append(str(res))

            return ", ".join(string_results), 200
        else:
            return str(result), 200
    except Exception as e:
        return str(e), 500
