    xpath_query = request.args.get('xpath')

    try:
        root = etree.fromstring(xml_src.encode('utf-8'))
        result = root.xpath(xpath_query)

        if isinstance(result, list):
            result_str = [etree.tostring(element, encoding='utf-8').decode('utf-8') if isinstance(element, etree._Element) else str(element) for element in result]
            return Response(str(result_str), mimetype='text/plain')
        else:
            return Response(str(result), mimetype='text/plain')

    except Exception as e:
        return Response(str(e), mimetype='text/plain', status=400)
