from lxml import etree

from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/xpath_query')
def xpath_query():
    '''
    Szerezd meg az XML forrást a kérésből az 'xml_src' használatával, és elemezd azt.
    Szerezd meg az xpath-ot a kérésből az 'xpath' használatával, és kérdezd le az XML-t az xpath használatával a /tag[@id='xpath'] számára.
    :visszatérés: A lekérdezés eredménye.
    '''
    xml_src = request.args.get('xml_src')
    xpath_query = request.args.get('xpath')

    if not xml_src or not xpath_query:
        return "Hiányzó xml_src vagy xpath paraméter", 400

    try:
        root = etree.fromstring(xml_src.encode('utf-8'))
        result = root.xpath(xpath_query)

        if isinstance(result, list):
            result_str = [etree.tostring(element, encoding='utf-8').decode('utf-8') if isinstance(element, etree._Element) else str(element) for element in result]
            return Response(str(result_str), mimetype='text/plain')
        else:
            return Response(str(result), mimetype='text/plain')

    except Exception as e:
        return f"Hiba történt: {str(e)}", 400
