from flask import Flask, request
import lxml.etree

app = Flask(__name__)

@app.post("/parse_xml")
def parse_xml():
    '''
    നിങ്ങളുടെ അഭ്യർത്ഥനയിൽ നിന്ന് 'xml_src' ഉപയോഗിച്ച് ഡാറ്റ നേടുക. അത് പദം ആയി XML ആയി പാഴ്സുചെയ്യുക. :ഫലമായി: XML ഒരു പദമായി.
    '''
    xml_src = request.form['xml_src']
    try:
        root = lxml.etree.fromstring(xml_src.encode('utf-8'))
        return dict_from_xml(root)
    except Exception as e:
        return str(e)

def dict_from_xml(node):
    """XML നോഡിൽ നിന്ന് ഒരു നിഘണ്ടു ഉണ്ടാക്കുക"""
    result = {}

    for element in node:
        sub_result = dict_from_xml(element)
        if element.tag in result:
            if type(result[element.tag]) is not list:
                result[element.tag] = [result[element.tag]]
            result[element.tag].append(sub_result)
        else:
            result[element.tag] = sub_result

    if node.text and not result:
        return node.text

    return result
```

