    '''
    നിങ്ങളുടെ അഭ്യർത്ഥനയിൽ നിന്ന് 'xml_src' ഉപയോഗിച്ച് ഡാറ്റ നേടുക. അത് പദം ആയി XML ആയി പാഴ്സുചെയ്യുക. :ഫലമായി: XML ഒരു പദമായി.
    '''
    xml_src = request.form['xml_src']
    root = lxml.etree.fromstring(xml_src)

    def xml_to_dict(element):
        d = {}
        for child in element:
            if len(child):
                d[child.tag] = xml_to_dict(child)
            else:
                d[child.tag] = child.text
        return d

    return xml_to_dict(root)
