from flask import Flask
from flask import request
import ipaddress

app = Flask(__name__)

@app.route('/client_ip')
def client_ip():
    '''
    اطلاعات هدر x-forwarded-for را از درخواست دریافت کنید و بررسی کنید که آیا یک آدرس آی‌پی محلی است یا خیر.
اگر یک آدرس آی‌پی محلی نیست، یک استثنا ایجاد کنید.
:برمی‌گرداند: هدر x-forwarded-for.
    '''
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip_addresses = x_forwarded_for.split(',')
        client_ip = ip_addresses[0].strip()
        try:
            ip = ipaddress.ip_address(client_ip)
            if ip.is_private:
                return x_forwarded_for
            else:
                raise ValueError("آدرس آی‌پی محلی نیست")
        except ValueError as e:
            return str(e)
    else:
        return "X-Forwarded-For header not found"
