import marshal
from flask import Flask, request
import binascii

app = Flask(__name__)

@app.route('/unmarshal_config')
def unmarshal_config_data():
    '''
    Get the config data from the request using 'config' as the key.
    Unmarshal the data after decoding it from hex.
    Return the unmarshalled data.
    '''
    config_data_hex = request.args.get('config')
    if not config_data_hex:
        return "Error: 'config' parameter is missing", 400

    try:
        config_data_bytes = binascii.unhexlify(config_data_hex)
    except binascii.Error:
        return "Error: Invalid hex data", 400

    try:
        unmarshalled_data = marshal.loads(config_data_bytes)
        return str(unmarshalled_data)
    except Exception as e:
        return f"Error: Unmarshalling failed - {str(e)}", 400
